begin;
select no_plan();
select has_table('private','publication_imports','publication intents remain in a private schema');
select has_table('private','publication_revision_provenance','immutable source provenance is recorded');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('publication_imports','publication_import_assets','publication_revision_provenance','publication_import_settings','publication_cleanup_tokens','publication_public_downloads') and c.relrowsecurity),6::bigint,'every private publication table has RLS');
select ok(not has_table_privilege('authenticated','private.publication_import_assets','insert'),'browser cannot attest an asset');
select ok(not has_table_privilege('hub_app_server','private.publication_import_assets','update'),'server must use guarded asset function');
select ok(not has_function_privilege('authenticated','private.commit_publication_import(uuid,jsonb)','execute'),'browser cannot bypass byte verification or call private writer');
select ok(not has_function_privilege('anon','private.commit_publication_import(uuid,jsonb)','execute'),'anonymous caller cannot commit');
select ok(not has_function_privilege('service_role','private.commit_publication_import(uuid,jsonb)','execute'),'service JWT does not become an editor');
select ok(has_function_privilege('hub_app_server','private.commit_publication_import(uuid,jsonb)','execute'),'dedicated application connection can invoke guarded commit');
select ok(not has_function_privilege('authenticated','private.verify_publication_asset(uuid,text,text,integer,text)','execute'),'browser cannot fake checked asset bytes');
select ok(not has_function_privilege('authenticated','private.consume_publication_cleanup(text)','execute'),'browser cannot consume maintenance capabilities');
select is((select public from storage.buckets where id='hub-publications'),false,'publication bucket remains private');
select is((select permissive from pg_policies where schemaname='storage' and tablename='objects' and policyname='publication_objects_private'),'RESTRICTIVE','a broad unrelated Storage policy cannot expose staging files');
select is((select max_video_bytes from private.publication_import_settings where singleton),26214400,'deployment initially advertises conservative 25MiB limit');
select throws_ok('select private.publication_import_access()','28000','Current application session required.','postgres caller cannot fabricate an app-owned SMS session');
select throws_ok($$select private.consume_publication_cleanup(repeat('a',64))$$,'42501','Server maintenance required.','cleanup cannot run under a substituted native role');
select ok((select pg_get_constraintdef(oid) like '%carebase.learning%' and pg_get_constraintdef(oid) like '%publication%' and pg_get_constraintdef(oid) like '%caremetric-go%' and pg_get_constraintdef(oid) like '%intel%' from pg_constraint where conname='app_delegations_audience_check'),'publication audience preserves learning receipt, Go and Intel capabilities');
select is((select count(*) from pg_trigger where tgname in ('publication_provenance_immutable','publication_revision_immutable','publication_asset_immutable','publication_change_lock')),4::bigint,'revision and byte immutability plus publication locking are installed');
select ok(not has_table_privilege('hub_app_server','private.publication_public_downloads','insert'),'public tickets require guarded server functions');
select ok(not has_function_privilege('anon','private.issue_publication_public_download(text,uuid,text,text)','execute'),'anonymous browser cannot issue transport authority');
select ok(not has_function_privilege('authenticated','private.consume_publication_public_download(text)','execute'),'browser cannot consume public transport tickets');
select ok(not has_function_privilege('service_role','private.publication_public_object(uuid,text)','execute'),'a service JWT cannot substitute for public policy evaluation');
select throws_ok($$select private.publication_public_object(gen_random_uuid(),'primary')$$,'42501','Application server required.','public policy RPC rejects substituted native connections');
select * from finish();
rollback;
